// Retry-budget controller: pure decision function + CLI.

const REQUIRED_FIELDS = [
  'attempt',
  'elapsedMs',
  'baseMs',
  'maxDelayMs',
  'budgetMs',
  'retryAfterMs',
  'retryable',
];

function isNonNegativeSafeInteger(v) {
  return Number.isSafeInteger(v) && v >= 0;
}

function isPositiveSafeInteger(v) {
  return Number.isSafeInteger(v) && v >= 1;
}

function validateOptions(o) {
  if (o === null || o === undefined || Array.isArray(o) || typeof o !== 'object') {
    throw new Error('options must be a non-null, non-array object');
  }
  for (const field of REQUIRED_FIELDS) {
    if (!(field in o)) {
      throw new Error(`missing required field: ${field}`);
    }
  }
  if (!isPositiveSafeInteger(o.attempt)) {
    throw new Error('attempt must be a positive safe integer');
  }
  for (const field of ['elapsedMs', 'baseMs', 'maxDelayMs', 'budgetMs']) {
    if (!isNonNegativeSafeInteger(o[field])) {
      throw new Error(`${field} must be a nonnegative safe integer`);
    }
  }
  if (o.retryAfterMs !== null && !isNonNegativeSafeInteger(o.retryAfterMs)) {
    throw new Error('retryAfterMs must be null or a nonnegative safe integer');
  }
  if (typeof o.retryable !== 'boolean') {
    throw new Error('retryable must be a boolean');
  }
}

// Capped exponential delay: baseMs * 2 ** (attempt - 1), capped at maxDelayMs.
// Must be exact for every valid safe-integer attempt without overflow or
// loops proportional to attempt.
function exponentialDelay(baseMs, maxDelayMs, attempt) {
  if (baseMs === 0) return 0;
  if (maxDelayMs === 0) return 0;
  // If baseMs >= maxDelayMs the cap applies immediately.
  if (baseMs >= maxDelayMs) return maxDelayMs;
  // Find the smallest exponent e such that baseMs * 2^e >= maxDelayMs.
  // e = ceil(log2(maxDelayMs / baseMs)), computed exactly via bit lengths.
  // For numbers a < b with a, b positive integers: ceil(log2(b/a)) =
  // bitLength(b) - bitLength(a) when b/a is not a power of two, and
  // bitLength(b) - bitLength(a) when it is (since b/a = 2^k =>
  // bitLength(b) = bitLength(a) + k exactly for integers).
  // Actually: for positive integers a, b, ceil(log2(b/a)) =
  //   bitLength(b) - bitLength(a)  if b >= a and b/a is not a power of 2
  //   bitLength(b) - bitLength(a)  if b/a is a power of 2 (exact)
  // Both cases give bitLength(b) - bitLength(a) when b >= a.
  // Wait: a=3, b=4: bitLength(4)=3, bitLength(3)=2, diff=1. log2(4/3)=0.415, ceil=1. OK.
  // a=3, b=5: bitLength(5)=3, bitLength(3)=2, diff=1. log2(5/3)=0.737, ceil=1. OK.
  // a=3, b=6: bitLength(6)=3, bitLength(3)=2, diff=1. log2(6/3)=1, ceil=1. OK.
  // a=3, b=7: bitLength(7)=3, bitLength(3)=2, diff=1. log2(7/3)=1.22, ceil=2. WRONG!
  // So the bit-length trick is not sufficient. Use a different approach.
  //
  // Safe approach: if attempt - 1 >= 64, then 2^(attempt-1) > 2^63 > any
  // safe integer, so baseMs * 2^(attempt-1) overflows any safe integer and
  // is certainly >= maxDelayMs (since maxDelayMs <= MAX_SAFE_INTEGER < 2^53
  // and baseMs >= 1). So return maxDelayMs.
  // Otherwise attempt - 1 <= 63, and 2^(attempt-1) fits in a double exactly
  // (it's a power of two). baseMs * 2^(attempt-1) may overflow to Infinity
  // or exceed maxDelayMs; check before multiplying.
  const exponent = attempt - 1;
  if (exponent >= 53) {
    // baseMs >= 1, so baseMs * 2^53 >= 2^53 > MAX_SAFE_INTEGER >= maxDelayMs.
    return maxDelayMs;
  }
  const power = 2 ** exponent; // exact: power of two, exponent < 53
  const product = baseMs * power;
  if (product >= maxDelayMs) return maxDelayMs;
  return product;
}

export function nextRetry(options) {
  validateOptions(options);
  if (options.retryable === false) {
    return { retry: false, delayMs: null, reason: 'non-retryable' };
  }
  const expDelay = exponentialDelay(options.baseMs, options.maxDelayMs, options.attempt);
  const wait = options.retryAfterMs !== null ? Math.max(expDelay, options.retryAfterMs) : expDelay;
  const remaining = options.budgetMs - options.elapsedMs;
  if (remaining < 0 || wait > remaining) {
    return { retry: false, delayMs: null, reason: 'budget-exhausted' };
  }
  return { retry: true, delayMs: wait, reason: 'scheduled' };
}

// --- CLI ---

const isMain = (() => {
  try {
    const entry = process.argv[1];
    if (!entry) return false;
    return import.meta.url === new URL(`file://${entry}`).href;
  } catch {
    return false;
  }
})();

if (isMain) {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    process.stderr.write('usage: node retry-budget.js INPUT_JSON_FILE\n');
    process.exit(2);
  }
  let raw;
  try {
    raw = await import('node:fs/promises').then((m) => m.readFile(args[0], 'utf8'));
  } catch (err) {
    process.stderr.write(`failed to read input file: ${err.message}\n`);
    process.exit(2);
  }
  let options;
  try {
    options = JSON.parse(raw);
  } catch (err) {
    process.stderr.write(`invalid JSON: ${err.message}\n`);
    process.exit(2);
  }
  try {
    const result = nextRetry(options);
    process.stdout.write(JSON.stringify(result) + '\n');
    process.exit(0);
  } catch (err) {
    process.stderr.write(`invalid options: ${err.message}\n`);
    process.exit(2);
  }
}

