import('./retry-budget.js').then(({nextRetry}) => {
  const assert = (await import('node:assert/strict')).default;
  // frozen object works
  const frozen = Object.freeze({attempt:1,elapsedMs:0,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:true});
  assert.deepEqual(nextRetry(frozen),{retry:true,delayMs:10,reason:'scheduled'});
  // huge attempt, zero base
  assert.deepEqual(nextRetry({attempt:9007199254740991,elapsedMs:0,baseMs:0,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:true}),{retry:true,delayMs:0,reason:'scheduled'});
  // huge attempt, nonzero base -> capped
  assert.deepEqual(nextRetry({attempt:9007199254740991,elapsedMs:0,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:true}),{retry:true,delayMs:100,reason:'scheduled'});
  // retryAfterMs not capped by maxDelayMs
  assert.deepEqual(nextRetry({attempt:1,elapsedMs:0,baseMs:10,maxDelayMs:100,budgetMs:10000,retryAfterMs:5000,retryable:true}),{retry:true,delayMs:5000,reason:'scheduled'});
  // budget boundary equality: wait == remaining is allowed
  assert.deepEqual(nextRetry({attempt:1,elapsedMs:990,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:true}),{retry:true,delayMs:10,reason:'scheduled'});
  // budget exceeded: wait > remaining
  assert.deepEqual(nextRetry({attempt:1,elapsedMs:991,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:true}),{retry:false,delayMs:null,reason:'budget-exhausted'});
  // elapsedMs > budgetMs
  assert.deepEqual(nextRetry({attempt:1,elapsedMs:1001,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:true}),{retry:false,delayMs:null,reason:'budget-exhausted'});
  // invalid: attempt 0
  assert.throws(()=>nextRetry({attempt:0,elapsedMs:0,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:true}),Error);
  // invalid: attempt not integer
  assert.throws(()=>nextRetry({attempt:1.5,elapsedMs:0,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:true}),Error);
  // invalid: attempt too large (not safe integer)
  assert.throws(()=>nextRetry({attempt:9007199254740992,elapsedMs:0,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:true}),Error);
  // invalid: null
  assert.throws(()=>nextRetry(null),Error);
  // invalid: array
  assert.throws(()=>nextRetry([]),Error);
  // invalid: retryable not boolean, still validates other fields
  assert.throws(()=>nextRetry({attempt:1,elapsedMs:0,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:'yes'}),Error);
  // validate even when retryable false
  assert.throws(()=>nextRetry({attempt:0,elapsedMs:0,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:false}),Error);
  // extra fields ignored
  assert.deepEqual(nextRetry({attempt:1,elapsedMs:0,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:true,extra:42}),{retry:true,delayMs:10,reason:'scheduled'});
  // does not mutate input
  const inp={attempt:1,elapsedMs:0,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:true};
  const before=JSON.stringify(inp);
  nextRetry(inp);
  assert.equal(JSON.stringify(inp),before);
  console.log('ALL API ASSERTIONS PASSED');
});
