import assert from 'node:assert/strict';
import { nextRetry } from './retry-budget.js';

// frozen object works
const frozen = Object.freeze({ attempt: 1, elapsedMs: 0, baseMs: 10, maxDelayMs: 100, budgetMs: 1000, retryAfterMs: null, retryable: true });
assert.deepEqual(nextRetry(frozen), { retry: true, delayMs: 10, reason: 'scheduled' });

// huge attempt, zero base -> zero delay
assert.deepEqual(nextRetry({ attempt: 9007199254740991, elapsedMs: 0, baseMs: 0, maxDelayMs: 100, budgetMs: 1000, retryAfterMs: null, retryable: true }), { retry: true, delayMs: 0, reason: 'scheduled' });

// huge attempt, nonzero base -> capped at maxDelayMs
assert.deepEqual(nextRetry({ attempt: 9007199254740991, elapsedMs: 0, baseMs: 10, maxDelayMs: 100, budgetMs: 1000, retryAfterMs: null, retryable: true }), { retry: true, delayMs: 100, reason: 'scheduled' });

// moderate attempt exact: baseMs=10, attempt=5 -> 10*2^4=160, capped at 100
assert.deepEqual(nextRetry({ attempt: 5, elapsedMs: 0, baseMs: 10, maxDelayMs: 100, budgetMs: 1000, retryAfterMs: null, retryable: true }), { retry: true, delayMs: 100, reason: 'scheduled' });

// moderate attempt exact below cap: baseMs=10, attempt=3 -> 10*2^2=40
assert.deepEqual(nextRetry({ attempt: 3, elapsedMs: 0, baseMs: 10, maxDelayMs: 100, budgetMs: 1000, retryAfterMs: null, retryable: true }), { retry: true, delayMs: 40, reason: 'scheduled' });

// retryAfterMs not capped by maxDelayMs
assert.deepEqual(nextRetry({ attempt: 1, elapsedMs: 0, baseMs: 10, maxDelayMs: 100, budgetMs: 10000, retryAfterMs: 5000, retryable: true }), { retry: true, delayMs: 5000, reason: 'scheduled' });

// retryAfterMs smaller than exp delay -> exp delay wins
assert.deepEqual(nextRetry({ attempt: 3, elapsedMs: 0, baseMs: 10, maxDelayMs: 100, budgetMs: 10000, retryAfterMs: 5, retryable: true }), { retry: true, delayMs: 40, reason: 'scheduled' });

// budget boundary equality: wait == remaining is allowed
